import sys

data = list(map(int, sys.stdin.read().split()))
n, target = data[0], data[1]
a = data[2:2+n]
lo, hi = 0, n - 1
ans = -1
while lo <= hi:
    mid = (lo + hi) // 2
    if a[mid] == target:
        ans = mid
        break
    if a[lo] <= a[mid]:
        if a[lo] <= target < a[mid]:
            hi = mid - 1
        else:
            lo = mid + 1
    else:
        if a[mid] < target <= a[hi]:
            lo = mid + 1
        else:
            hi = mid - 1
print(ans)
